import type { IconProps } from '@openfin/ui-library';

import { createLogger } from '@common/utils/logger';
import { getCurrentOFWindow } from '@common/utils/window';

const logger = createLogger('enterprise.RightControlsContainer');

import { BrowserButtonType, ToolbarOptions, WindowStateButtonOptions } from '@client-platform/shapes';

export const handleMinimizeClick = () => {
    getCurrentOFWindow()
        .minimize()
        .catch((err) => {
            logger.error('handleMinimizeClick', 'Failed to minimize window', {
                error: err instanceof Error ? err.message : String(err)
            });
        });
};

