import { css } from 'styled-components';

import debounce from 'lodash.debounce';

/**
 * TL;DR
 * We toggle `has-left-overflow` / `has-right-overflow` on the GoldenLayout tab strip (`.lm_tabs`) so CSS can
 * show/hide the left/right “overflow fade” shadows based on the *actual* scroll position.
 *
 * Why this is needed now (but wasn't in 22.3.28):
 * In 22.3.28 the edge fades were effectively “CSS-driven” (scroll effects + palette-based gradients) and didn’t
 * require us to compute left/right overflow state. After the theme/tokens + styling refactor, that approach became
 * unreliable/inconsistent and also didn’t satisfy the updated requirement to show correct shadows without hover,
 * so we drive the visibility state from JS instead.
 */
const LEFT_OVERFLOW_CLASS = 'has-left-overflow';
const RIGHT_OVERFLOW_CLASS = 'has-right-overflow';
const TAB_GROUP_INIT_ATTR = 'data-view-tab-overflow-init';
const NEW_TAB_BUTTON_WIDTH = 32;
const resizeObservers = new WeakMap<Element, ResizeObserver>();

/**
 * We must debounce per LayoutContainer instance.
 *
 * Multiple pages/layouts can exist at once (inactive ones are often `display: none`).
 * A single shared `debounce(toggleScrollShadows, 100)` would cause calls from different pages to
 * overwrite/cancel each other, which can leave the *active* page with stale shadow positioning/classNames
 * until another layout event happens (e.g. creating a new view tab).
 *
 * WeakMap is intentional:
 * - keys are DOM nodes (layout container refs)
 * - we don't want to leak timers across page close/unmount
 */
const debouncedToggleByContainer = new WeakMap<HTMLDivElement, ReturnType<typeof debounce>>();

export const updateViewTabOverflowClassNames = (tabGroup: Element) => {
    const maxScrollLeft = tabGroup.scrollWidth - tabGroup.clientWidth;
    if (maxScrollLeft <= 1) {
        tabGroup.classList.remove(LEFT_OVERFLOW_CLASS, RIGHT_OVERFLOW_CLASS);
        return;
    }

    const hasLeftOverflow = tabGroup.scrollLeft > 0;
    const hasRightOverflow = tabGroup.scrollLeft < maxScrollLeft - 1;

    tabGroup.classList.toggle(LEFT_OVERFLOW_CLASS, hasLeftOverflow);
    tabGroup.classList.toggle(RIGHT_OVERFLOW_CLASS, hasRightOverflow);
};

const scheduleOverflowUpdate = (tabGroup: Element) => {
    /**
     * We measure `scrollWidth/clientWidth/scrollLeft` to decide which overflow shadows should be visible.
     * This code runs immediately after we mutate the DOM around the tab strip (e.g. moving the + button,
     * appending shadow elements, and adjusting header padding for controls).
     *
     * Without deferring, those measurements can be stale because the browser may not have applied styles/layout
     * for the current tick yet. That leads to flaky behavior where overflow classes are missing until the user
     * scrolls, hovers, or another layout-triggering event occurs.
     *
     * `requestAnimationFrame` schedules the measurement for the next frame, after layout has been flushed,
     * without us forcing a synchronous reflow.
     */
    if (typeof requestAnimationFrame === 'function') {
        requestAnimationFrame(() => updateViewTabOverflowClassNames(tabGroup));
        return;
    }
    updateViewTabOverflowClassNames(tabGroup);
};

const ensureResizeObserver = (tabGroup: Element) => {
    if (typeof ResizeObserver === 'undefined') return;
    if (resizeObservers.has(tabGroup)) return;

    const observer = new ResizeObserver(() => scheduleOverflowUpdate(tabGroup));
    observer.observe(tabGroup);
    resizeObservers.set(tabGroup, observer);
};

const applyCondensedTabClassNames = (tabGroup: Element) => {
    const tabs = tabGroup.querySelectorAll('.lm_tab');
    if (!tabs.length) return;

    let condensedTabClassName = '';
    const { width } = tabs[0].getBoundingClientRect();

    if (width === 24) {
        condensedTabClassName = 'view-tab-condensed-sm';
    } else if (width < 44) {
        condensedTabClassName = 'view-tab-condensed-md';
    } else if (width <= 56) {
        condensedTabClassName = 'view-tab-condensed-lg';
    }

    tabs.forEach((tab) => {
        tab.classList.forEach((className) => className.includes('view-tab-') && tab.classList.remove(className));
        if (condensedTabClassName) {
            tab.classList.add(condensedTabClassName);
        }
    });
};

// Enables horizontal scroll on tabs
const handleTabContainerScroll = (event: WheelEvent) => {
    const { deltaX, deltaY } = event;
    const tabHeader = (event.target as HTMLElement).closest('.lm_tabs');
    if (Math.abs(deltaY) > Math.abs(deltaX)) {
        tabHeader.scrollLeft += deltaY - deltaX;
    }
};

// Scrolls tab container when mouse nears edge of tab header
const handleAutoScrollOnTabDrag = (event: MouseEvent) => {
    // event.target can be a Text node when dragging over text content
    const target = event.target as Node;
    const element = target.nodeType === Node.ELEMENT_NODE ? (target as Element) : target.parentElement;
    if (!element) return;

    const tabHeader = element.closest('.lm_header');
    if (!tabHeader) return;

    const tabGroup = tabHeader.querySelector('.lm_tabs') as HTMLDivElement;
    if (!tabGroup) return;

    const isDraggingTab = !!tabGroup.querySelector('.lm_drop_tab_placeholder');

    if (isDraggingTab) {
        const tabGroupRect = tabGroup.getBoundingClientRect();
        if (event.clientX < tabGroupRect.left + 12) {
            tabGroup.scrollBy({ left: -1 });
        }
        if (event.clientX > tabGroupRect.right - 12) {
            tabGroup.scrollBy({ left: 1 });
        }
    }
};

const toggleScrollShadows = (containerRef: HTMLDivElement) => {
    const tabHeaders = containerRef.querySelectorAll('.lm_header');
    tabHeaders.forEach((tabHeader: HTMLDivElement) => {
        const tabGroup = tabHeader.querySelector('.lm_tabs');
        if (!tabGroup) return;

        const scrollShadows = tabGroup.querySelectorAll('.scroll-shadow');
        const newTabButton: HTMLDivElement = tabHeader.querySelector('.newTabButton');
        const controlsContainer: HTMLDivElement = tabHeader.querySelector('.lm_controls');

        // Create space for of absolute-positioned controls container (e.g. popout icon)
        tabHeader.style.paddingRight = `${controlsContainer?.offsetWidth}px`;

        // tabs.length > 1 prevents scroll shadows when moving tab from
        // tab header that only has ONE tab
        const tabs = tabGroup.querySelectorAll('.lm_tab');
        if (tabGroup.scrollWidth > tabGroup.clientWidth && tabs.length > 1) {
            // Move new tab button from tab list to tab header so
            // 1) Plus button doesn't move since it's not part of the tab list
            // 2) New tabs can properly scroll into view
            // Golden layouts will automatically re-add a plus button into the tab list
            // but we will hide it using CSS in the presence of this button.
            if (newTabButton?.parentElement.classList.contains('lm_tabs')) {
                tabHeader.insertBefore(newTabButton, tabGroup);
            }

            let tabGroupRightScrollShadow = Array.from(scrollShadows).find((element) =>
                element.classList.contains('right-scroll-shadow')
            ) as HTMLDivElement;
            // Apply scroll shadows
            if (!scrollShadows.length) {
                const tabGroupLeftScrollShadow = document.createElement('div');
                tabGroupLeftScrollShadow.classList.add('scroll-shadow', 'left-scroll-shadow');
                tabGroupRightScrollShadow = document.createElement('div');
                tabGroupRightScrollShadow.classList.add('scroll-shadow', 'right-scroll-shadow');

                tabGroup.appendChild(tabGroupLeftScrollShadow);
                tabGroup.appendChild(tabGroupRightScrollShadow);
            }

            if (!tabGroup.hasAttribute(TAB_GROUP_INIT_ATTR)) {
                tabGroup.setAttribute(TAB_GROUP_INIT_ATTR, 'true');
                tabGroup.addEventListener('wheel', handleTabContainerScroll);
                tabGroup.addEventListener('scroll', () => updateViewTabOverflowClassNames(tabGroup));
                tabHeader.addEventListener('drag', handleAutoScrollOnTabDrag);
            }

            // Offset absolute positioned newTab button and scroll shadow if there is a visible controls container (e.g. popout button)
            if (newTabButton) {
                newTabButton.style.right = `${controlsContainer.offsetWidth}px`;
            }
            tabGroupRightScrollShadow.style.right = `${
                (controlsContainer?.offsetWidth || 0) + (newTabButton ? NEW_TAB_BUTTON_WIDTH : 0)
            }px`;

            updateViewTabOverflowClassNames(tabGroup);
            ensureResizeObserver(tabGroup);
            scheduleOverflowUpdate(tabGroup);
        } else if (tabGroup.scrollWidth <= tabGroup.clientWidth) {
            // Remove the tab header plus button we inserted for the scrolling case
            if (newTabButton?.parentElement.classList.contains('lm_header')) {
                newTabButton.remove();
            }

            if (scrollShadows.length) {
                scrollShadows[0].remove();
                scrollShadows[1].remove();
            }

            tabGroup.classList.remove(LEFT_OVERFLOW_CLASS, RIGHT_OVERFLOW_CLASS);
        }

        applyCondensedTabClassNames(tabGroup);
    });
};

export const toggleScrollShadowsNow = (containerRef: HTMLDivElement) => {
    if (!containerRef) return;
    toggleScrollShadows(containerRef);
};

/**
 * Debounced version for noisy events (resize, tab-created, view-detached, etc.).
 * Uses the per-container WeakMap so different pages don't clobber each other's scheduled updates.
 */
export const debouncedToggleScrollShadows = (containerRef: HTMLDivElement) => {
    if (!containerRef) return;
    const existing = debouncedToggleByContainer.get(containerRef);
    if (existing) {
        existing(containerRef);
        return;
    }

    const debounced = debounce(toggleScrollShadows, 100);
    debouncedToggleByContainer.set(containerRef, debounced);
    debounced(containerRef);
};

export const getViewTabTitleOverflowShadow = (isTabHoveredOrActive: boolean, isCloseButtonShowing: boolean) => {
    const startToken = isTabHoveredOrActive
        ? 'var(--color-enterprise-view-tab-overflow-start-hover)'
        : 'var(--color-enterprise-view-tab-overflow-start-default)';

    const middleToken = isTabHoveredOrActive
        ? 'var(--color-enterprise-view-tab-overflow-middle-hover)'
        : 'var(--color-enterprise-view-tab-overflow-middle-default)';

    const endToken = isTabHoveredOrActive
        ? 'var(--color-enterprise-view-tab-overflow-end-hover)'
        : 'var(--color-enterprise-view-tab-overflow-end-default)';

    if (isCloseButtonShowing) {
        return css`
            background: linear-gradient(90deg, ${endToken} 0%, ${middleToken} 28%, ${startToken} 56%);
        `;
    } else {
        return css`
            background: linear-gradient(90deg, ${endToken} 50%, ${middleToken} 75%, ${startToken} 90%);
        `;
    }
};
