import { useCallback, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';

import OpenFin from '@openfin/core';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { selectSelectedViewsForPage } from '@enterprise/slices/tab-focus';

import { checkViewUrl } from '@enterprise/components/ControlBar/SearchMenu/utils';

import store from '@enterprise/store';

/*
 * This hook checks if the selected view is navigated to the provided URL.
 */
export const useIsSelectedViewNavigated = ({ url }: { url: string }) => {
    const [isViewNavigatedToUrl, setIsViewNavigatedToUrl] = useState<boolean>(false);
    const [selectedView, setSelectedView] = useState<OpenFin.View | null>(null);
    const { pageId } = useSelector(selectActivePage);
    const selectedViews = selectSelectedViewsForPage(store.getState(), pageId);

    const checkViewUrlCallback = useCallback(
        (view: OpenFin.View | null) => checkViewUrl(view, url, setIsViewNavigatedToUrl),
        [url]
    );

    useEffect(() => {
        if (!selectedView) {
            return;
        }

        const handleUrlChange = () => {
            checkViewUrlCallback(selectedView);
        };

        selectedView.addListener('url-changed', handleUrlChange);
        return () => {
            selectedView.removeListener('url-changed', handleUrlChange);
        };
    }, [selectedView, checkViewUrlCallback]);

    useEffect(() => {
        const initializeSelectedView = async () => {
            if (selectedViews.length === 0) {
                setSelectedView(null);
                return;
            }

            const view = fin.View.wrapSync(selectedViews[0]);
            setSelectedView(view);
            checkViewUrlCallback(view);
        };

        initializeSelectedView();
    }, [selectedViews, checkViewUrlCallback]);

    return { isViewNavigatedToUrl, selectedView };
};
