import React from 'react';

import { Icon } from '@openfin/ui-library';

import { enterpriseToolbarTestIds } from '@common/utils/test-ids';

import { useTranslation } from '@common/api/i18next';

import useWindowFocusState from '@common/hooks/useWindowFocusState';
import { SidePanelComponent, useSidePanelContext } from '@enterprise/context/SidePanelContext';
import { useBookmarksPanelFocus } from '@enterprise/hooks/useBookmarksPanelFocus';
import { IconButtonContainer } from '@enterprise/styles/buttons';

const BookmarksPanelButton: React.FC = () => {
    const windowFocused = useWindowFocusState();
    const { t } = useTranslation();
    const { toggleSidePanelComponent, bookmarksButtonRef } = useSidePanelContext();
    const { isBookmarksPanelOpen } = useBookmarksPanelFocus();

    return (
        <IconButtonContainer
            ref={bookmarksButtonRef}
            title={t('bookmarks.bookmarksPanel')}
            onClick={() => toggleSidePanelComponent(SidePanelComponent.Bookmarks)}
            windowFocused={windowFocused}
            selected={isBookmarksPanelOpen}
            aria-expanded={isBookmarksPanelOpen}
            data-testid={enterpriseToolbarTestIds.bookmarksPanelButton}
        >
            <Icon icon="BookmarkFilled" />
        </IconButtonContainer>
    );
};

export default BookmarksPanelButton;
