import React from 'react';

import { Box, Icon } from '@openfin/ui-library';
import { enterpriseStyles } from '@openfin/ui-library/enterprise-css-selectors';

import { countViews } from '@common/utils/layout';

import type { AttachedPageInternal } from '@common/api/pages/shapes';

import { CloseIconWrapper, LargeCustomIcon, UnsavedChangesIcon } from './styles';

interface CloseButtonProps extends React.ButtonHTMLAttributes<unknown> {
    options?: AttachedPageInternal['closeButton'];
    parentHover: boolean;
    page: AttachedPageInternal;
    pageActive: boolean;
    isEnterprise: boolean;
    isSchemeDark: boolean;
    hideCloseButton: boolean;
}

const CloseButton: React.FC<CloseButtonProps> = ({
    options,
    parentHover,
    page,
    pageActive,
    isEnterprise,
    hideCloseButton,
    ...rest
}) => {
    if (options?.hidden) return <Box padding="xsmall" />;

    const { hasUnsavedChanges, unsavedIconUrl } = page;
    const viewCount = countViews(page.layout.content);

    if (isEnterprise && viewCount > 1 && hasUnsavedChanges && (!parentHover || hideCloseButton)) {
        return (
            <CloseIconWrapper
                className={enterpriseStyles.tabsCloseButton}
                isEnterprise
                hideCloseButton={hideCloseButton}
                {...rest}
            >
                <div className={enterpriseStyles.tabsCloseButtonIcon}>
                    {unsavedIconUrl ? (
                        <LargeCustomIcon iconURL={unsavedIconUrl} data-testid="unsavedChangesIcon" />
                    ) : (
                        <UnsavedChangesIcon data-testid="unsavedChangesIcon" />
                    )}
                </div>
            </CloseIconWrapper>
        );
    }
    if (!isEnterprise || pageActive || (parentHover && !hideCloseButton)) {
        return (
            <CloseIconWrapper
                className={enterpriseStyles.tabsCloseButton}
                isEnterprise={isEnterprise}
                hideCloseButton={hideCloseButton}
                {...rest}
            >
                <div className={enterpriseStyles.tabsCloseButtonIcon}>
                    <Icon icon="Cross2Icon" size="small" />
                </div>
            </CloseIconWrapper>
        );
    }
    return <></>;
};

export default CloseButton;
