import { MutableRefObject, useCallback, useEffect } from 'react';

import { OpenFin } from '@openfin/core';

import { mapContentComponentState } from '@common/utils/layout';
import { currentOFIdentity, getCurrentOFWindow } from '@common/utils/window';

import { getActivePageForWindow } from '@enterprise/api/pages/attached';

import { zoomViewIn, zoomViewOut } from '@enterprise/utils/zoom-controls';

import { useIsWindows } from './useIsWindows';

interface UseSetUpZoomHotkeysProps {
    selectedView: OpenFin.View;
    zoomPercentRef: MutableRefObject<number>;
    showDialog: (openedViaMouseClick?: boolean) => void;
}

/**
 * This hook is used to set up the zoom hotkeys for the selected view and the current window.
 */
export const useSetUpZoomHotkeys = ({ selectedView, zoomPercentRef, showDialog }: UseSetUpZoomHotkeysProps) => {
    const isWindows = useIsWindows();

    const handleZoomSupertabHotkey = useCallback(
        async (e: OpenFin.Events.WindowEvents.HotkeyEvent | OpenFin.Events.ViewEvents.HotkeyEvent) => {
            // FIXME: https://openfin.jira.com/browse/WRK-5563
            // eventually could just use `fin.Platform.Layout.getCurrentSync().getCurrentViews()` instead
            // of keying off redux state as it is probably more dependable and less brute-force
            const activeLayout = (await getActivePageForWindow()).layout;
            const views = mapContentComponentState(activeLayout.content).map((viewOptions) => {
                return fin.View.wrapSync({ name: viewOptions.name, uuid: currentOFIdentity.uuid });
            });
            switch (e.key) {
                // Windows uses (+) when the shift key is pressed and mac uses (=)
                case '=':
                case '+':
                    views.forEach(async (view) => {
                        if (
                            view.identity.uuid === selectedView.identity.uuid &&
                            view.identity.name === selectedView.identity.name
                        ) {
                            // Need to set the zoom percent for the selected view bc the ZoomButton determines if its renders
                            // based on if the zoom percent is 100 or not
                            zoomPercentRef.current = await zoomViewIn(view);
                        } else {
                            await zoomViewIn(view);
                        }
                        showDialog();
                    });
                    break;
                // Windows uses (_) when the shift key is pressed and mac uses (-)
                case '-':
                case '_':
                    views.forEach(async (view) => {
                        if (
                            view.identity.uuid === selectedView.identity.uuid &&
                            view.identity.name === selectedView.identity.name
                        ) {
                            zoomPercentRef.current = await zoomViewOut(view);
                        } else {
                            await zoomViewOut(view);
                        }
                        showDialog();
                    });
                    break;
            }
        },
        [showDialog, zoomPercentRef, selectedView]
    );

    const handleZoomViewHotkey = useCallback(
        async (e: OpenFin.Events.WindowEvents.HotkeyEvent | OpenFin.Events.ViewEvents.HotkeyEvent) => {
            switch (e.key) {
                case '=':
                    zoomPercentRef.current = await zoomViewIn(selectedView);
                    showDialog();
                    break;
                case '-':
                    zoomPercentRef.current = await zoomViewOut(selectedView);
                    showDialog();
                    break;
            }
        },
        [showDialog, zoomPercentRef, selectedView]
    );

    const handleWindowHotkey = useCallback(
        async (e: OpenFin.Events.WindowEvents.HotkeyEvent) => {
            if (e.inputType === 'keyDown' && (isWindows ? e.ctrlKey : e.metaKey)) {
                if (e.shiftKey) {
                    handleZoomSupertabHotkey(e);
                } else {
                    handleZoomViewHotkey(e);
                }
            }
        },
        [isWindows, handleZoomSupertabHotkey, handleZoomViewHotkey]
    );

    const handleViewHotkey = useCallback(
        async (e: OpenFin.Events.ViewEvents.HotkeyEvent) => {
            if (e.inputType === 'keyDown' && (isWindows ? e.ctrlKey : e.metaKey)) {
                if (e.shiftKey) {
                    handleZoomSupertabHotkey(e);
                } else {
                    handleZoomViewHotkey(e);
                }
            }
        },
        [isWindows, handleZoomSupertabHotkey, handleZoomViewHotkey]
    );

    useEffect(() => {
        if (selectedView) {
            selectedView.addListener('hotkey', handleViewHotkey);
        }
        return () => {
            if (selectedView) {
                selectedView.removeListener('hotkey', handleViewHotkey);
            }
        };
    }, [selectedView, handleViewHotkey]);

    useEffect(() => {
        const window = getCurrentOFWindow();
        window.addListener('hotkey', handleWindowHotkey);
        return () => {
            window.removeListener('hotkey', handleWindowHotkey);
        };
    }, [handleWindowHotkey]);
};
