import { Dispatch, FC, MutableRefObject, useCallback, useEffect, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import type OpenFin from '@openfin/core';

import { showInfo, showSuccess } from '@common/utils/indicators/showIndicator';
import { createLogger } from '@common/utils/logger';
import { Menu } from '@common/utils/menu';
import { RightMenuConfig } from '@common/utils/menu-config';

const logger = createLogger('enterprise.ColorLinkingButton');

import { t } from '@common/api/i18next';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { highlightAllInteropViews, updateContextGroup } from '@enterprise/api/color-linking';
import { raiseJoinContextGroupAnalytics, raiseLeaveContextGroupAnalytics } from '@enterprise/api/controls';

import {
    selectLayoutsWithSelectedViews,
    selectShowAllContextGroups,
    toggleContextGroupOutlines
} from '@enterprise/slices/tab-focus';

import { BrowserButtonType } from '@client-platform/shapes';
import { useLanguageChange } from '@common/hooks/useLanguageChange';

import MenuButton from '../../../../MenuButton/MenuButton';
import { defaultButtonPropMap } from '../../../utils';
import { getColorLinkingMenu } from '../../menus/menuConfig';
import { PredefinedIconUrl } from '../MenuButtonIcon';

export enum ColorLinkingChannelTypes {
    JOIN_GROUP = 'join-group',
    LEAVE_GROUP = 'leave-group',
    SHOW_HIDE_GROUPS = 'show-hide-groups'
}

export type ColorLinkingChannelMessageData =
    | {
          type: ColorLinkingChannelTypes.JOIN_GROUP | ColorLinkingChannelTypes.LEAVE_GROUP;
          channelId: string;
          colorName: string;
      }
    | {
          type: ColorLinkingChannelTypes.SHOW_HIDE_GROUPS;
      };

interface Props {
    tooltip?: string;
    iconUrl?: string;
}

const MENU_TYPE: Menu = Menu.COLOR_LINK;

const makeColorLinkingMenuHandler =
    (dispatchRef: MutableRefObject<Dispatch<unknown>>, selectedViewsRef: MutableRefObject<OpenFin.Identity[]>) =>
    async (ev: MessageEvent<ColorLinkingChannelMessageData>) => {
        switch (ev.data.type) {
            case ColorLinkingChannelTypes.JOIN_GROUP:
                try {
                    const colorName = ev.data.colorName;
                    await updateContextGroup(selectedViewsRef.current, ev.data.channelId);
                    fin.Window.getCurrentSync().focus();
                    showSuccess({
                        message: t('successIndicator.namedContextGroupApplied', { colorName: colorName }),
                        parentBrowserName: fin.me.name
                    });
                    selectedViewsRef.current.forEach((view) => raiseJoinContextGroupAnalytics(colorName, view));
                } catch (e) {
                    logger.warn('colorLinkingMenuHandler', 'Failed to update context group', {
                        error: e instanceof Error ? e.message : String(e)
                    });
                    // Grab focus to close color linking menu
                    fin.Window.getCurrentSync().focus();
                    showInfo({
                        message: t('infoIndicator.colorLinkAttempt'),
                        parentBrowserName: fin.me.name
                    });
                }
                break;
            case ColorLinkingChannelTypes.LEAVE_GROUP: {
                const colorName = ev.data.colorName;
                await updateContextGroup(selectedViewsRef.current, ev.data.channelId);
                fin.Window.getCurrentSync().focus();
                showSuccess({
                    message:
                        selectedViewsRef.current.length > 1
                            ? t('successIndicator.viewRemoved')
                            : t('successIndicator.viewsRemoved'),
                    parentBrowserName: fin.me.name
                });
                selectedViewsRef.current.forEach((view) => raiseLeaveContextGroupAnalytics(colorName, view));
                break;
            }
            case ColorLinkingChannelTypes.SHOW_HIDE_GROUPS:
                dispatchRef.current(toggleContextGroupOutlines());
        }
    };

const makeLayoutReadyHandler = (showAllContextGroupsRef: MutableRefObject<boolean>) => () => {
    if (showAllContextGroupsRef.current) {
        highlightAllInteropViews();
    }
};

const ColorLinkingButton: FC<Props> = ({ tooltip, iconUrl }) => {
    const dispatch = useDispatch();
    const dispatchRef = useRef(dispatch);
    dispatchRef.current = dispatch;
    const activePage = useSelector(selectActivePage);

    const layoutsWithSelectedViews = useSelector(selectLayoutsWithSelectedViews);
    const selectedViews = layoutsWithSelectedViews[activePage.layoutContainerKey];
    const selectedViewsRef = useRef(selectedViews);
    selectedViewsRef.current = selectedViews;

    const showAllContextGroups = useSelector(selectShowAllContextGroups);
    const showAllContextGroupsRef = useRef(showAllContextGroups);
    showAllContextGroupsRef.current = showAllContextGroups;

    const [menuButtonConfig, setMenuButtonConfig] = useState<RightMenuConfig | null>(null);

    const disabled = !!activePage.isLocked;

    const onLanguageChange = useCallback(() => {
        Promise.all([getColorLinkingMenu(t('toolbar.colorLinking')), fin.me.interop.getContextGroups()] as const).then(
            ([menu, groups]) => {
                setMenuButtonConfig({
                    ...menu,
                    windowOptions: {
                        ...menu.windowOptions,
                        defaultWidth: 32 * Math.min(groups.length + 1, 10) + 4 // buttonWidth * buttons# + 4 px to account for margins
                    }
                });
            }
        );
    }, []);

    useLanguageChange(onLanguageChange);

    useEffect(() => {
        const channelToMenu = new BroadcastChannel(`color-linking-${fin.me.name}`);
        channelToMenu.onmessage = makeColorLinkingMenuHandler(dispatchRef, selectedViewsRef);

        const handleLayoutReady = makeLayoutReadyHandler(showAllContextGroupsRef);

        // When new layout is applied, golden-layout will re-create some elements.
        // Re-apply color-linking styles when this happens.
        (fin.me as OpenFin.Window).on('layout-ready', handleLayoutReady);

        return () => {
            (fin.me as OpenFin.Window).removeListener('layout-ready', handleLayoutReady);
            channelToMenu.close();
        };
    }, []);

    const customToolTip = tooltip || menuButtonConfig?.title;
    const defaultIcon = defaultButtonPropMap[BrowserButtonType.ColorLinking].iconProps.icon;

    if (!menuButtonConfig) {
        return null;
    }

    return (
        <MenuButton
            type={MENU_TYPE}
            config={menuButtonConfig}
            params={{ selectedViews: JSON.stringify(selectedViews) }}
            tooltip={customToolTip}
            disabled={disabled}
        >
            <PredefinedIconUrl customIconUrl={iconUrl} uiLibIcon={defaultIcon} disabled={disabled} />
        </MenuButton>
    );
};

export default ColorLinkingButton;
