import { useEffect, RefObject } from 'react';

import type { AttachedPageInternal } from '@common/api/pages/shapes';
import { countViews, mapContentComponentState } from '@common/utils/layout';
import { useFocusManager } from '@common/hooks/useFocusManager';

/**
 * Hook to handle Enter and Space key presses on the page title button and its descendants.
 * Uses event delegation to catch keyboard events from the title button and its child elements.
 * Only enables keyboard navigation for active single page views.
 *
 * @param buttonRef - Ref to the title button element (must not be null)
 * @param page - The page object to check if it's an active single page view
 */
export const useKeyboardViewNavigation = (buttonRef: RefObject<HTMLButtonElement>, page: AttachedPageInternal) => {
    const { focusView } = useFocusManager();
    const { isActive, attachedPageType, layout, singleViewName } = page;

    // Only enable keyboard navigation for active single page views
    // For enterprise: check attachedPageType
    // For browser: check view count in layout
    const isSingleView =
        attachedPageType === 'singleView' ||
        (attachedPageType === undefined && layout?.content && countViews(layout.content) === 1);
    const shouldEnable = isActive && isSingleView;

    useEffect(() => {
        const buttonElement = buttonRef.current;
        if (!buttonElement || !shouldEnable) {
            return;
        }

        const handleKeyDown = async (event: KeyboardEvent) => {
            // Only handle Enter and Space keys
            if (event.key !== 'Enter' && event.key !== ' ') {
                return;
            }

            // Verify the event target is within the title button's subtree
            if (!buttonElement.contains(event.target as Node)) {
                return;
            }

            // Prevent default behavior for both Enter and Space
            event.preventDefault();

            // Get the view name - use singleViewName if available, otherwise get from layout
            let viewName = singleViewName;
            if (!viewName && layout?.content) {
                const componentStates = mapContentComponentState(layout.content);
                if (componentStates.length === 1 && componentStates[0].name) {
                    viewName = componentStates[0].name;
                }
            }

            // Get the view from the page and focus it
            if (viewName) {
                const viewIdentity = { uuid: fin.me.uuid, name: viewName };
                // Use focus manager for centralized focus coordination
                focusView(viewIdentity, 'user-click');
            }
        };

        buttonElement.addEventListener('keydown', handleKeyDown);

        return () => {
            buttonElement.removeEventListener('keydown', handleKeyDown);
        };
    }, [buttonRef, isActive, attachedPageType, singleViewName, layout, focusView]);
};
