import styled, { css } from 'styled-components';

import { CloseIconWrapper, EnterpriseTitleButton, PageIconContainer } from './styles';

interface ContainerProps {
    isActive: boolean;
    isSingleView: boolean;
    windowFocused: boolean;
    pageHasUnsavedChanges: boolean;
    dragDisabled?: boolean;
    isSchemeDark?: boolean;
    isDragging?: boolean;
    isDropRegion?: boolean;
    shouldHideBottomBorder?: boolean;
}

// Container styled-components
// Note: Borders, backgrounds, and text overflow gradient are handled by ui-library CSS
// We only define layout properties here that are specific to workspace
const BaseContainer = styled.div<ContainerProps>`
    align-items: center;
    display: ${({ isDragging }) => (isDragging ? 'none' : 'flex')};
    flex-shrink: 0;
    max-height: 100%;
`;

const EnterpriseContainer = styled(BaseContainer).attrs<ContainerProps>(({ shouldHideBottomBorder }) => ({
    'data-hide-bottom-border': shouldHideBottomBorder ? 'true' : 'false'
}))`
    /* Layout - Flex */
    flex: 1 1 100%;
    align-items: center;
    justify-content: center;
    position: relative;
    padding-left: ${({ theme }) => theme.px.base};
    gap: ${({ theme }) => theme.px.xsmall};
    min-width: 40px;
    max-width: 180px;
    width: 180px;
    overflow: hidden;
    white-space: nowrap;
    background-clip: ${({ isSingleView }) => isSingleView && 'padding-box'};

    /* Workspace-specific: Drop region styling */
    ${({ isDropRegion }) =>
        isDropRegion &&
        css`
            border: 2px solid var(--color-role-border-accent-base);

            /* Hide both text overflow gradients when drop region is active */
            &::after,
            .enterprise-tabs__title::after {
                display: none;
            }
        `}

    /* Workspace-specific: Opacity when window unfocused */
    & > * {
        opacity: ${({ windowFocused }) => !windowFocused && '0.5'};
    }

    &:hover span {
        opacity: 1;
    }

    /* Workspace-specific: Hover background color for inactive tabs */
    &:hover {
        background-color: ${({ isActive, isSchemeDark }) =>
            !isActive && (isSchemeDark ? 'var(--color-role-background-3)' : 'var(--color-role-background-1)')};
    }

    &::before {
        content: '';
        display: ${({ isDropRegion }) => (isDropRegion ? 'block' : 'none')};
        position: absolute;
        height: 100%;
        width: 100%;
        right: 0;
        left: 0;
        top: 0;
        background-color: var(--color-role-background-accent-base);
        opacity: 0.25;
        z-index: 2;
    }

    /* Text overflow gradient removed - now handled by ui-library CSS (.enterprise-tabs__tab-item::after) */

    &.enterprise-tabs__tab-item--sm {
        padding: 0 6px;

        ${PageIconContainer} {
            margin-right: unset;
            display: ${({ isActive, pageHasUnsavedChanges }) => (isActive || pageHasUnsavedChanges) && 'none'};
        }

        /* If there is no page icon, show the title instead */
        ${EnterpriseTitleButton}:only-child {
            display: ${({ isActive }) => !isActive && 'inherit'};
        }

        ${EnterpriseTitleButton} {
            display: none;
        }

        ${CloseIconWrapper} {
            margin-right: 0;
            display: ${({ isActive, pageHasUnsavedChanges }) => !(isActive || pageHasUnsavedChanges) && 'none'};
        }
    }

    &.enterprise-tabs__tab-item--md,
    &.enterprise-tabs__tab-item--lg {
        /* If there is no page icon; show the title instead */
        div:empty + ${EnterpriseTitleButton} {
            display: inherit;
        }

        /* Show x button when tab active; always show dirty indicator */
        ${CloseIconWrapper} {
            display: ${({ isActive, pageHasUnsavedChanges }) => !(isActive || pageHasUnsavedChanges) && 'none'};
        }
    }

    /* Hide page icon when tab active; show dirty indicator instead of page icon */
    &.enterprise-tabs__tab-item--md ${PageIconContainer} {
        display: ${({ isActive, pageHasUnsavedChanges }) => (isActive || pageHasUnsavedChanges) && 'none'};
    }
`;

export default EnterpriseContainer;
