import { useMemo } from 'react';

import { type ThemedTaskbarIconProps, useUpdateTaskbarIcon } from '@common/hooks/useUpdateTaskbarIcon';
import { useWindowOptions } from '@common/hooks/useWindowOptions';

export const useBrowserTaskbarIcon = () => {
    const { workspacePlatform, windowIcon } = useWindowOptions();

    const taskbarIcon = useMemo<ThemedTaskbarIconProps | undefined>(() => {
        const icon = workspacePlatform?.icon;
        const lightIcon = typeof icon === 'object' ? icon.light : icon || windowIcon;
        const darkIcon = typeof icon === 'object' ? icon.dark : icon || windowIcon;
        if (lightIcon || darkIcon) {
            return {
                light: lightIcon || darkIcon,
                dark: darkIcon || lightIcon,
                custom: true
            };
        }
        return undefined;
    }, [workspacePlatform?.icon, windowIcon]);

    useUpdateTaskbarIcon(taskbarIcon);
};
